class Words2Numbers:

    # Symbolic constants to replace magic numbers
    HUNDRED = 100
    THOUSAND = 1000
    TEN = 10

    def __init__(self):
        self.numwords = {}
        self.units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.scales = ["hundred", "thousand", "million", "billion", "trillion"]

        self.numwords["and"] = (1, 0)
        for idx, word in enumerate(self.units):
            self.numwords[word] = (1, idx)
        for idx, word in enumerate(self.tens):
            self.numwords[word] = (1, idx * self.TEN)
        for idx, word in enumerate(self.scales):
            self.numwords[word] = (10 ** (idx * 3 or 2), 0)

        self._ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self._ordinal_endings = [('ieth', 'y'), ('th', '')]

    @property
    def ordinal_words(self):
        """Encapsulate Collection: getter for ordinal_words"""
        return self._ordinal_words

    @property
    def ordinal_endings(self):
        """Encapsulate Collection: getter for ordinal_endings"""
        return self._ordinal_endings

    def _strip_ordinal_ending(self, word):
        """Extract Method: strips ordinal endings from a word"""
        for ending, replacement in self._ordinal_endings:
            if word.endswith(ending):
                return "%s%s" % (word[:-len(ending)], replacement)
        return word

    def _process_word(self, word):
        """
        Extract Method / Replace Nested Conditional with Guard Clauses:
        Process a single word, returning (scale, increment, is_valid_number)
        """
        if word in self._ordinal_words:
            return (1, self._ordinal_words[word], True)

        processed_word = self._strip_ordinal_ending(word)

        if processed_word not in self.numwords:
            return (None, None, False)

        return (*self.numwords[processed_word], True)

    def text2int(self, textnum):
        """
        Refactored using:
        - Extract Method
        - Replace Nested Conditional with Guard Clauses
        - Introduce Explaining Variable
        - Replace Loop with Pipeline (conceptually, though we keep the loop for statefulness)
        """
        clean_text = textnum.replace('-', ' ')

        current = result = 0
        curstring = ""
        onnumber = False

        for raw_word in clean_text.split():
            scale, increment, is_valid = self._process_word(raw_word)

            if not is_valid:
                if onnumber:
                    curstring += repr(result + current) + " "
                curstring += raw_word + " "
                result = current = 0
                onnumber = False
                continue

            current = current * scale + increment
            if scale and scale > self.HUNDRED:
                result += current
                current = 0
            onnumber = True

        if onnumber:
            curstring += repr(result + current)

        return curstring

    def is_valid_input(self, textnum):
        """
        Refactored using:
        - Extract Method
        - Replace Nested Conditional with Guard Clauses
        - Parameterize Method (conceptually)
        """
        clean_text = textnum.replace('-', ' ')

        for raw_word in clean_text.split():
            _, _, is_valid = self._process_word(raw_word)
            if not is_valid:
                return False

        return True
